import { initializeBindings, Pickles } from '../../bindings.js';
import { synchronousRunners } from '../provable/core/provable-context.js';
import { Provable } from '../provable/provable.js';
import { provable } from '../provable/types/provable-derivers.js';
import { Struct } from '../provable/types/struct.js';
import { Field } from '../provable/wrapped.js';
import { inCircuitVkHash } from './zkprogram.js';

export { VerificationKey };

class VerificationKey extends Struct({
  ...provable({ data: String, hash: Field }),
  toJSON({ data, hash }: { data: string; hash: Field }) {
    return { data, hash: hash.toString() };
  },
}) {
  static async dummy(): Promise<VerificationKey> {
    await initializeBindings();
    const [, data, hash] = Pickles.dummyVerificationKey();
    return new VerificationKey({
      data,
      hash: Field(hash),
    });
  }

  static dummySync(): VerificationKey {
    return new VerificationKey({
      ...RAW_VERIFICATION_KEY,
      hash: Field(RAW_VERIFICATION_KEY.hash),
    });
  }

  public static async fromData(data: string): Promise<VerificationKey> {
    let hash: Field;
    await Provable.runAndCheck(async () => {
      let vk = Pickles.sideLoaded.vkToCircuit(() => data);
      let hash_ = inCircuitVkHash(vk);
      Provable.asProver(() => {
        hash = hash_.toConstant();
      });
    });
    return new VerificationKey({ data, hash: hash! });
  }

  static async checkValidity(key: VerificationKey): Promise<boolean> {
    try {
      let { runAndCheckSync } = await synchronousRunners();

      runAndCheckSync(() => {
        let vk = Pickles.sideLoaded.vkToCircuit(() => key.data);
        let inCircuitHash = inCircuitVkHash(vk);
        inCircuitHash.assertEquals(key.hash);
      });
      return true;
    } catch {
      return false;
    }
  }
}

const RAW_VERIFICATION_KEY = {
  hash: '3392518251768960475377392625298437850623664973002200885669375116181514017494',
  // oxlint-disable-line
  data: '',
};
